const APP_TITLE="Happy English Adventure";
const APP_VERSION="v19";
const APP_TAG="kid-chest";
const APP_VERSION_LABEL=`${APP_TITLE}`;
document.title=`${APP_TITLE} ${APP_VERSION} ${APP_TAG}`;

function topicImage(t){return TOPIC_IMAGES[t.id]?`<img class="topicIcon" src="${TOPIC_IMAGES[t.id]}" alt="${esc(t.name)}">`:`<span class="topicEmoji">${t.icon}</span>`}



function mergeTopics(saved){const map=new Map((Array.isArray(saved)?saved:[]).map(t=>[t.id,t]));for(const t of TOPICS){if(!map.has(t.id))map.set(t.id,t)}return [...map.values()].sort((a,b)=>(+a.order)-(+b.order))}
function mergeBuiltinCards(saved){const map=new Map((Array.isArray(saved)?saved:[]).map(c=>[c.id,c]));for(const c of BUILTIN_CARDS){if(!map.has(c.id))map.set(c.id,c)}return [...map.values()]}
const state={screen:"profiles",topics:mergeTopics(load(STORE.topics,TOPICS)),profiles:load(STORE.profiles,[]),activeId:load(STORE.active,null),cards:[],topic:null,questions:[],quizConfig:null,practice:false,result:null,soundEnabled:load("hea_v3_sound",true)};
store(STORE.topics,state.topics);



const root=document.getElementById("root");
function load(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function store(k,v){localStorage.setItem(k,JSON.stringify(v))}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]))}
function avatarImg(kind,size='big'){const src=AVATAR_MAP[kind]||AVATAR_MAP.boy;return `<img class="avatarPic ${size}" src="${src}" alt="${kind==='boy'?'男生角色':'女生角色'}">`}
function pretty(s){return s.replaceAll("_"," ")}
function uid(){return crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random())}
function shuffled(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function active(){return state.profiles.find(p=>p.id===state.activeId)}
function saveProfiles(){store(STORE.profiles,state.profiles);store(STORE.active,state.activeId)}
function updateProfile(fn){state.profiles=state.profiles.map(p=>p.id===state.activeId?fn(p):p);saveProfiles()}
function rewardGroupFor(p){return p?.avatar==="girl"?"girl":"boy"}
function rewardThemesFor(p){return REWARD_THEMES[rewardGroupFor(p)]||REWARD_THEMES.boy}
function pickNextReward(p){const themes=rewardThemesFor(p),rewards={...(p.rewardImages||{})};for(const t of themes){const got=rewards[t.id]||[],left=t.imgs.map((_,i)=>i).filter(i=>!got.includes(i));if(left.length){const idx=left[Math.floor(Math.random()*left.length)];return {theme:t,index:idx,src:t.imgs[idx],done:got.length+1===t.imgs.length}}}return null}
function rewardCollectionHtml(p){const lockSrc=rewardGroupFor(p)==="girl"?"girl.png":"boy.png";return rewardThemesFor(p).map(t=>{const got=p.rewardImages?.[t.id]||[];const done=got.length===t.imgs.length;return `<div class="rewardAlbum ${done?"complete":""}"><div class="rewardAlbumTop"><div class="rewardAlbumTitle"><b>${done?"🏅 ":"✨ "}${t.name}</b><small>${done?"全套收集完成！":"收集進度加油中"}</small></div><span class="rewardCount">${got.length}/${t.imgs.length}</span></div><div class="rewardGrid">${t.imgs.map((src,i)=>got.includes(i)?`<div class="rewardSlot got"><span class="slotBadge">${i+1}</span><img src="${src}" alt="${t.name}"></div>`:`<div class="rewardSlot locked chestLocked"><span class="slotBadge">${i+1}</span><img class="lockedChestImg" src="${lockSrc}" alt="未收集寶箱"></div>`).join("")}</div></div>`}).join("")}
function db(){return new Promise((ok,no)=>{const r=indexedDB.open("happyEnglishAdventureStableV2",1);r.onupgradeneeded=()=>r.result.createObjectStore("cards",{keyPath:"id"});r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
async function replaceCards(cards){const d=await db();return new Promise((ok,no)=>{const tx=d.transaction("cards","readwrite"),s=tx.objectStore("cards");s.clear();cards.forEach(c=>s.put(c));tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
async function getCards(){const d=await db();return new Promise((ok,no)=>{const r=d.transaction("cards").objectStore("cards").getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
function toggleSound(){state.soundEnabled=!state.soundEnabled;store("hea_v3_sound",state.soundEnabled);render()}function speak(word){if(!state.soundEnabled||typeof speechSynthesis==="undefined"||typeof SpeechSynthesisUtterance==="undefined")return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(pretty(word));u.lang="en-US";u.rate=.78;u.pitch=1.05;speechSynthesis.speak(u)}
let _audioCtx;function beep(kind){if(!state.soundEnabled)return;const AudioCtor=window.AudioContext||window.webkitAudioContext;if(!AudioCtor)return;if(!_audioCtx)_audioCtx=new AudioCtor();if(!_audioCtx)return;if(_audioCtx.state==="suspended")_audioCtx.resume();const o=_audioCtx.createOscillator(),g=_audioCtx.createGain();o.connect(g);g.connect(_audioCtx.destination);o.frequency.value=kind==="good"?740:kind==="chest"?520:kind==="click"?600:240;o.type=kind==="bad"?"sawtooth":"sine";g.gain.setValueAtTime(.08,_audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,_audioCtx.currentTime+(kind==="chest"?.55:kind==="click"?.08:.18));o.start();o.stop(_audioCtx.currentTime+(kind==="chest"?.55:kind==="click"?.08:.18))}
function header(home=true){const p=active();return `<header class="header"><div class="brand"><img class="brandIcon" src="data:image/png;base64," alt="小精靈圖示"> ${APP_VERSION_LABEL}</div><div class="right"><div class="right">${p?`<div class="profilePill" onclick="go('myProfile')">${avatarImg(p.avatar,"sm")}<span class="name">${esc(p.name)}</span></div>`:""}<button class="iconBtn soundToggle${state.soundEnabled?"":" muted"}" onclick="toggleSound()" aria-label="${state.soundEnabled?"暫停音效":"播放音效"}" title="${state.soundEnabled?"暫停音效":"播放音效"}">${state.soundEnabled?`<img class="btnIcon" src="${IMG_SPEAKER_OFF}" alt="暫停">`:`<img class="btnIcon" src="${IMG_SPEAKER_ON}" alt="播放">`}</button>${home?`<button class="iconBtn" onclick="go('menu')" aria-label="回到首頁" title="回到首頁"><img class="btnIcon" src="${IMG_HOME}" alt="首頁"></button>`:""}</div></header>`}
function btn(label,cls,action,disabled=""){return `<button ${disabled?"disabled":""} class="btn ${cls}" onclick="${action}">${label}</button>`}
function go(screen){beep("click");state.screen=screen;render()}
async function boot(){try{const saved=await getCards();state.cards=saved.length?mergeBuiltinCards(saved):[...BUILTIN_CARDS]}catch(e){state.cards=[...BUILTIN_CARDS]}render()}
function render(){
  root.innerHTML='<header id="appHeader"></header><main id="page"></main>';
  const s=state.screen;
  if(s==="profiles"){document.getElementById("appHeader").style.display="none";renderProfiles();return}
  document.getElementById("appHeader").style.display="";document.getElementById("appHeader").innerHTML=header(!["menu"].includes(s));
  if(s==="menu")renderMenu(); if(s==="admin")renderAdmin(); if(s==="learnTopics")renderTopicPicker(); if(s==="learn")renderLearn();
  if(s==="count")renderCount(); if(s==="quizSetup")renderQuizSetup(); if(s==="quiz")renderQuiz(); if(s==="result")renderResult();
  if(s==="mistakes")renderMistakes(); if(s==="practiceResult")renderPracticeResult(); if(s==="myProfile")renderProfile();
}
function renderProfiles(){
 root.innerHTML=`<main class="hero center"><div class="heroArtWrap"><img class="heroArt" src="data:image/png;base64," alt="可愛男女小小冒險家首頁插圖"></div><div class="homeTitle"><div class="homeTitleEn">Happy English Adventure</div></div><p>選一位小小冒險家，一起聽聲音、答題、開寶箱！</p><div class="grid profiles">${state.profiles.map(p=>`<button class="profileCard" onclick="chooseProfile('${p.id}')">${avatarImg(p.avatar,"big")}${esc(p.name)}</button>`).join("")}</div><div id="create">${btn("＋ 建立小小冒險家","primary","showCreate()")}</div></main>`;
}
function showCreate(){
 document.getElementById("create").innerHTML=`<div class="card"><input id="playerName" class="field" maxlength="12" placeholder="輸入名字或暱稱"><div class="avatarSelect"><button id="boy" class="avatarChoice selected" onclick="pickAvatar('boy')" aria-label="選擇男生角色">${avatarImg("boy","big")}</button><button id="girl" class="avatarChoice" onclick="pickAvatar('girl')" aria-label="選擇女生角色">${avatarImg("girl","big")}</button></div>${btn("開始冒險","primary","createProfile()")}</div>`; state.avatar="boy"
}
function pickAvatar(a){state.avatar=a;document.getElementById("boy").classList.toggle("selected",a==="boy");document.getElementById("girl").classList.toggle("selected",a==="girl")}
function createProfile(){const n=document.getElementById("playerName").value.trim();if(!n)return;const p={id:uid(),name:n,avatar:state.avatar||"boy",puzzleSet:0,puzzlePieces:{},badges:[],rewardImages:{},mistakes:{},learned:[],quizzes:0};state.profiles.push(p);state.activeId=p.id;saveProfiles();go("menu")}
function chooseProfile(id){state.activeId=id;saveProfiles();go("menu")}
function renderMenu(){
 const custom=load(STORE.ready,false);document.getElementById("page").innerHTML=`<div class="banner"><div><h2>今天也來開寶箱！</h2><p>${custom?"新教材準備好了，一起答題拿星星、開寶箱！":"看圖片、聽聲音、答題拿星星，完成挑戰就能開寶箱！"}</p></div><button class="iconBtn" onclick="go('admin')">⚙️</button></div><div class="grid menu">
 <button style="background:#34d399" onclick="go('learnTopics')"><img class="menuIcon" src="data:image/png;base64," alt="開始學習"><span class="menuLabel">看單字</span></button>
 <button style="background:#fb923c" onclick="go('quizSetup')"><img class="menuIcon" src="data:image/png;base64," alt="開始測驗"><span class="menuLabel">開始挑戰</span></button>
 <button style="background:#f472b6" onclick="go('mistakes')"><img class="menuIcon" src="data:image/png;base64," alt="錯題本"><span class="menuLabel">小精靈複習</span></button>
 <button style="background:#38bdf8" onclick="go('myProfile')"><img class="menuIcon" src="data:image/png;base64," alt="我的檔案"><span class="menuLabel">我的寶物</span></button></div>`;
}
function renderAdmin(){
 document.getElementById("page").innerHTML=`<h2 class="pageTitle">家長管理區</h2><div class="grid admin">
 <section class="card"><h3>內建正式教材</h3><p>已整合 <b>${BUILTIN_CARDS.length} 張圖卡</b>，可直接開始遊戲，不需要再匯入 ZIP。</p>${btn("恢復內建 "+BUILTIN_CARDS.length+" 張圖卡","primary","restoreBuiltin()")}<div id="status"></div></section>
 <section class="card"><h3>未來更新教材（選用）</h3><p class="small">僅限之後新增或替換圖卡時使用。匯入圖片會先縮小再儲存，避免大型圖片造成當機。</p><label class="btn green">📥 匯入更新 ZIP<input id="zipInput" type="file" accept=".zip" class="hidden"></label><p class="small">建議 ZIP 小於 60 MB；這次提供的 ${BUILTIN_CARDS.length} 張正式圖卡已內建，不需要再次匯入。</p></section>
 <section class="card"><h3>新增未來主題</h3><p class="small">新增全新主題前，先設定檔名中的主題 ID。</p><input id="newId" class="field" placeholder="例如 toys"><input id="newName" class="field" placeholder="例如 Toys">${btn("新增主題","green","addTopic()")}<p class="small">新增後檔名編號依畫面產生，例如 17_toys_ball_v01.png。</p></section></div>`;
 document.getElementById("zipInput").addEventListener("change",e=>importZip(e.target.files[0]));
}
function addTopic(){const id=document.getElementById("newId").value.trim(),name=document.getElementById("newName").value.trim();if(!id||!name)return;const num=String(Math.max(...state.topics.map(t=>+t.order),0)+1).padStart(2,"0");state.topics.push({order:num,id,name,icon:"📚"});store(STORE.topics,state.topics);renderAdmin()}
async function clearCards(){const d=await db();return new Promise((ok,no)=>{const tx=d.transaction("cards","readwrite"),s=tx.objectStore("cards");s.clear();tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
async function restoreBuiltin(){await clearCards();await replaceCards(BUILTIN_CARDS);state.cards=[...BUILTIN_CARDS];const el=document.getElementById("status");el.className="status";el.textContent=`已恢復內建教材：${BUILTIN_CARDS.length} 張圖片、${new Set(BUILTIN_CARDS.map(c=>c.topicId)).size} 個主題。`}
function reduceImage(entry){
 return entry.async("blob").then(blob=>new Promise((ok,no)=>{
  const img=new Image(),src=URL.createObjectURL(blob);
  img.onload=()=>{const max=640,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.round(img.width*scale),h=Math.round(img.height*scale),canvas=document.createElement("canvas");canvas.width=w;canvas.height=h;canvas.getContext("2d").drawImage(img,0,0,w,h);URL.revokeObjectURL(src);ok(canvas.toDataURL("image/jpeg",.86))};
  img.onerror=()=>{URL.revokeObjectURL(src);no(new Error("image decode failed"))};img.src=src;
 }))
}
async function importZip(file){
 if(!file)return;const el=document.getElementById("status");el.className="status";
 if(file.size>60*1024*1024){el.textContent="此 ZIP 過大，為避免當機不進行匯入。正式 150 張圖卡已內建，可直接使用。";return}
 el.textContent="正在讀取並壓縮更新圖片…";
 try{
   const zip=await JSZip.loadAsync(file),ordered=[...state.topics].sort((a,b)=>b.id.length-a.id.length),parsed=[],bad=[];
   for(const path of Object.keys(zip.files)){
    const entry=zip.files[path];if(entry.dir||!/\.png$/i.test(path))continue;
    const name=path.split("/").pop();let found=null;
    for(const t of ordered){const prefix=`${t.order}_${t.id}_`;if(name.startsWith(prefix)&&/_v\d+\.png$/i.test(name)){found={topic:t,word:name.slice(prefix.length).replace(/_v\d+\.png$/i,"")};break}}
    if(!found){bad.push(name);continue}
    const url=await reduceImage(entry);parsed.push({id:name,fileName:name,topicId:found.topic.id,word:found.word,url});
   }
   if(bad.length){el.textContent=`有 ${bad.length} 張無法辨識：${bad.slice(0,3).join("、")}。請檢查命名或先新增主題。`;return}
   if(!parsed.length){el.textContent="ZIP 中找不到可匯入的 PNG。";return}
   await replaceCards(parsed);state.cards=parsed;el.textContent=`更新完成：${parsed.length} 張圖片、${new Set(parsed.map(c=>c.topicId)).size} 個主題。`;
 }catch(err){el.textContent="ZIP 讀取失敗，請確認檔案格式與圖片內容。"}
}
function usableTopics(){return state.topics.filter(t=>state.cards.some(c=>c.topicId===t.id))}
const TOPIC_WORD_ORDER={numbers:["one","two","three","four","five","six","seven","eight","nine","ten"],greetings:["hello","hi","good_morning","good_afternoon","good_evening","goodbye","see_you","nice_to_meet_you","how_are_you","im_fine"]};
function orderedCards(topicId){
 const cards=state.cards.filter(c=>c.topicId===topicId),order=TOPIC_WORD_ORDER[topicId];
 if(!order)return cards;
 return [...cards].sort((a,b)=>{const ai=order.indexOf(a.word),bi=order.indexOf(b.word);return (ai<0?999:ai)-(bi<0?999:bi)});
}
function renderTopicPicker(){
 document.getElementById("page").innerHTML=`<h2 class="pageTitle">選擇學習主題</h2><div class="grid topics">${usableTopics().map(t=>`<button class="topic" onclick="chooseLearn('${t.id}')">${topicImage(t)}<span class="topicName">${esc(t.name)}</span><small>${state.cards.filter(c=>c.topicId===t.id).length} cards</small></button>`).join("")}</div>`;
}
function chooseLearn(id){state.topic=id;updateProfile(p=>({...p,learned:[...new Set([...(p.learned||[]),id])]}));go("learn")}
function cardImage(c,cl=""){return `<img class="${cl}" src="${c.url}" alt="${esc(pretty(c.word))}" onerror="this.outerHTML='<div class=\\'fallback answerImg\\'>🖼️<br>${esc(pretty(c.word))}</div>'">`}
function renderLearn(){
 const t=state.topics.find(x=>x.id===state.topic),cards=orderedCards(state.topic);state.learnPlays={};
  document.getElementById("page").innerHTML=`<div class="learnTop"><button class="btn sky backTopicBtn" onclick="go('learnTopics')">返回主題</button><h2 class="pageTitle">${esc(t.name)}</h2></div><p><b>點圖片就能聽發音 🔊</b></p><div class="grid cards">${cards.map(c=>`<button class="flash" onclick="openLearn('${c.id}')">${cardImage(c)}</button>`).join("")}</div>${btn("開始挑戰","orange","go('count')")}`;
}
function playLimited(id, bucket){const c=state.cards.find(x=>x.id===id);bucket[id]=bucket[id]||0;if(bucket[id]>=3)return;bucket[id]++;speak(c.word);const num=document.getElementById("playsLeft");if(num)num.textContent=3-bucket[id]}
function openLearn(id){const c=state.cards.find(x=>x.id===id);playLimited(id,state.learnPlays);document.body.insertAdjacentHTML("beforeend",`<div id="learnModal" class="modal"><div class="card"><button class="close" onclick="document.getElementById('learnModal').remove()">×</button><button onclick="playLimited('${c.id}',state.learnPlays)" style="background:none;width:100%">${cardImage(c,"answerImg")}</button><button class="btn sky" style="width:100%;margin-top:12px" onclick="playLimited('${c.id}',state.learnPlays)">🔊 聽發音（剩 <span id="playsLeft">${3-(state.learnPlays[id]||0)}</span> 次）</button></div></div>`)}
function renderCount(){document.getElementById("page").innerHTML=`<h2 class="pageTitle">選擇挑戰題數</h2><p class="center rewardHint">先玩 5 題，很快就能開寶箱！</p><div class="center countBtns" style="padding:35px">${btn("5 題","orange","startQuiz({mode:'single',topicIds:[state.topic],count:5})")} ${btn("10 題","orange","startQuiz({mode:'single',topicIds:[state.topic],count:10})")} ${btn("20 題","orange","startQuiz({mode:'single',topicIds:[state.topic],count:20})")}</div>`}
function renderQuizSetup(){
 state.setup={mode:"single",selected:[],count:5};
 document.getElementById("page").innerHTML=`<h2 class="pageTitle">開始挑戰</h2><div class="settingsRow"><button id="single" class="btn choice active" onclick="setMode('single')">單一主題</button><button id="mixed" class="btn choice" onclick="setMode('mixed')">混搭主題</button></div><p id="pickNote">請選 1 個主題</p><div id="setupTopics" class="grid topics"></div><div class="settingsRow" style="margin-top:25px"><button id="n5" class="btn orange" onclick="setCount(5)">5 題</button><button id="n10" class="btn" onclick="setCount(10)">10 題</button><button id="n20" class="btn" onclick="setCount(20)">20 題</button></div><button id="quizStart" class="btn green" disabled onclick="beginSetupQuiz()">開始闖關</button>`; paintSetupTopics()
}
function setMode(m){state.setup.mode=m;state.setup.selected=[];document.getElementById("single").classList.toggle("active",m==="single");document.getElementById("mixed").classList.toggle("active",m==="mixed");document.getElementById("pickNote").textContent=m==="mixed"?"請選至少 2 個主題":"請選 1 個主題";paintSetupTopics()}
function setCount(n){state.setup.count=n;[5,10,20].forEach(x=>{const el=document.getElementById("n"+x);if(el)el.classList.toggle("orange",n===x)})}
function paintSetupTopics(){document.getElementById("setupTopics").innerHTML=usableTopics().map(t=>`<button class="topic ${state.setup.selected.includes(t.id)?"selectedTopic":""}" onclick="toggleTopic('${t.id}')">${topicImage(t)}<span class="topicName">${esc(t.name)}</span></button>`).join("");document.getElementById("quizStart").disabled=state.setup.mode==="single"?state.setup.selected.length!==1:state.setup.selected.length<2}
function toggleTopic(id){beep("click");if(state.setup.mode==="single")state.setup.selected=[id];else state.setup.selected=state.setup.selected.includes(id)?state.setup.selected.filter(x=>x!==id):[...state.setup.selected,id];paintSetupTopics()}
function beginSetupQuiz(){beep("click");startQuiz({mode:state.setup.mode,topicIds:state.setup.selected,count:state.setup.count})}
function options(target,pool){return shuffled([target,...shuffled(pool.filter(c=>c.id!==target.id)).slice(0,3)])}
function assignTypes(cards){const types=shuffled([...Array(Math.ceil(cards.length/2)).fill("listen"),...Array(Math.floor(cards.length/2)).fill("sound")]);return cards.map((card,i)=>({card,type:types[i]}))}
function makeQuestions(config){
 const pool=state.cards.filter(c=>config.topicIds.includes(c.topicId));let qs=[];
 if(config.mode==="single"&&config.count===20){return shuffled(pool.slice(0,10).flatMap(card=>[{card,type:"listen",opts:options(card,pool)},{card,type:"sound",opts:options(card,pool)}]))}
 let selected=shuffled(pool).slice(0,Math.min(config.count,pool.length));while(selected.length<config.count)selected.push(shuffled(pool)[0]);
 return assignTypes(selected).map(q=>({...q,opts:options(q.card,pool)}))
}
function startQuiz(config){state.quizConfig=config;state.questions=makeQuestions(config);state.qIndex=0;state.score=0;state.practice=false;updateProfile(p=>({...p,learned:[...new Set([...(p.learned||[]),...config.topicIds])]}));go("quiz")}
function renderQuiz(){
  const q=state.questions[state.qIndex];state.qPlays={};state.lock=false;document.getElementById("appHeader").innerHTML=header(true);document.getElementById("page").innerHTML=`<div class="quizWrap"><div class="scorebar"><span>${state.practice?"小精靈複習":"闖關挑戰"} ${state.qIndex+1} / ${state.questions.length}</span><span>⭐ ${state.score}</span><button class="btn sky quizHomeBtn" onclick="go('menu')">🏠 回首頁</button></div><section class="card quizCard"><div id="feedback"></div><div id="quizInner" class="quizInner"></div></section></div>`;
 const inner=document.getElementById("quizInner");
 if(q.type==="listen") inner.innerHTML=`<h2>聽聲音，選圖片</h2><button id="targetSound" class="btn sky" onclick="quizSpeak('${q.card.id}','target')">🔊 播放聲音（剩 <span id="targetLeft">3</span> 次）</button><div class="options" style="margin-top:20px">${q.opts.map(c=>`<button class="imgOption" onclick="answer('${c.id}')">${cardImage(c,"answerImg")}</button>`).join("")}</div>`;
 else inner.innerHTML=`<h2>看圖片，聽聲音，選答案</h2>${cardImage(q.card,"answerImg target")}<div class="options">${q.opts.map((c,i)=>`<div class="audioOption"><button class="mic c${i}" onclick="quizSpeak('${c.id}','${c.id}')">🔊</button><p class="small">可聽 <span id="left_${CSS.escape(c.id)}">3</span> 次</p><button class="btn" onclick="answer('${c.id}')">選這個</button></div>`).join("")}</div>`;
}
function quizSpeak(id,key){if(state.lock)return;state.qPlays[key]=state.qPlays[key]||0;if(state.qPlays[key]>=3)return;state.qPlays[key]++;speak(state.cards.find(c=>c.id===id).word);const el=document.getElementById(key==="target"?"targetLeft":"left_"+CSS.escape(id));if(el)el.textContent=3-state.qPlays[key]}
function answer(id){
 if(state.lock)return;state.lock=true;const q=state.questions[state.qIndex],correct=id===q.card.id,next=state.score+(correct?1:0);if(correct)state.score=next;else updateProfile(p=>({...p,mistakes:{...(p.mistakes||{}),[q.card.id]:p.mistakes?.[q.card.id]||0}}));
 if(correct&&state.practice)updateProfile(p=>{const m={...(p.mistakes||{})},n=(m[q.card.id]||0)+1;if(n>=2)delete m[q.card.id];else m[q.card.id]=n;return {...p,mistakes:m}});
 beep(correct?"good":"bad");document.getElementById("feedback").innerHTML=`<div class="feedback ${correct?"good":"bad"}">${correct?"答對了！ ⭐":"再加油！"}</div>`;document.getElementById("quizInner").classList.add("shift");
 setTimeout(()=>{if(state.qIndex+1===state.questions.length){if(!state.practice)updateProfile(p=>({...p,quizzes:(p.quizzes||0)+1}));state.result={score:next,total:state.questions.length};go(state.practice?"practiceResult":"result")}else{state.qIndex++;renderQuiz()}},620)
}
function renderResult(){state.chestOpened=false;state.chestClicks=0;const r=state.result;const p=active(),group=rewardGroupFor(p)==="girl"?"女生角色":"男生角色";const isPerfect=r.score===r.total;const chestHTML=`<div class="chestStage"><button class="chestBtn bigChest" id="chest" onclick="openChest()" aria-label="開啟寶箱"><img class="chestImg" src="${REWARD_IMAGES.CHEST}" alt="寶箱"></button><p id="chestLabel" class="chestProgress"><b>點寶箱 3 次，打開今日寶物 0/3</b></p></div>`;document.getElementById("page").innerHTML=`<h2 class="pageTitle">挑戰完成，來開寶箱吧！</h2><div class="card result"><div class="score">⭐ ${r.score} / ${r.total}</div><p><b>${isPerfect?"太棒了！你今天超厲害！🌟":"完成挑戰！一起看看拿到什麼寶物吧！"}</b></p><p class="rewardHint">${group}寶物收藏｜點三下寶箱，就能拿到今日寶物</p>${chestHTML}<div id="reward"></div><div class="settingsRow" style="justify-content:center">${btn("再玩一次","orange","startQuiz(state.quizConfig)")}${btn("回主題","sky","go('learnTopics')")}${btn("我的寶物","primary","go('myProfile')")}</div></div>`}
function openChest(){if(state.chestOpened)return;state.chestClicks=(state.chestClicks||0)+1;beep("chest");const chest=document.getElementById("chest"),label=document.getElementById("chestLabel"),reward=document.getElementById("reward");chest.classList.remove("tap1","tap2","tap3","shake");void chest.offsetWidth;chest.classList.add("shake","tap"+Math.min(state.chestClicks,3));if(state.chestClicks<3){label.innerHTML=`<b>第 ${state.chestClicks} 下！寶箱亮晶晶 ${state.chestClicks}/3</b>`;reward.innerHTML=`<div class="reward pending">再點 ${3-state.chestClicks} 次，就能拿到新寶物！</div>`;return}state.chestOpened=true;let p=active(),picked=pickNextReward(p),msg="";chest.classList.add("opened");label.textContent="寶箱開啟了！";if(!picked){msg="這個角色的寶物已全部收集完成！";reward.innerHTML=`<div class="reward rewardReveal"><div style="font-size:64px">🎉</div><div><b>${msg}</b><br><small>可以換另一個角色繼續收集。</small></div></div>`;return}let rewards={...(p.rewardImages||{})},got=rewards[picked.theme.id]||[];rewards[picked.theme.id]=[...got,picked.index];let badges=[...(p.badges||[])];if(picked.done&&!badges.includes(picked.theme.id))badges.push(picked.theme.id);p={...p,rewardImages:rewards,badges};updateProfile(()=>p);msg=picked.done?`太棒了！${picked.theme.name} 全套收集完成！`:`哇！你拿到 ${picked.theme.name} 新寶物！`;reward.innerHTML=`<div class="reward rewardReveal"><img class="rewardBig" src="${picked.src}" alt="${picked.theme.name}"><div><b>${msg}</b><br><small>已收藏 ${rewards[picked.theme.id].length}/${picked.theme.imgs.length}，快到「我的寶物」看看吧！</small></div></div>`}
function renderMistakes(){const ids=Object.keys(active().mistakes||{}),cards=state.cards.filter(c=>ids.includes(c.id));document.getElementById("page").innerHTML=`<h2 class="pageTitle">小精靈複習</h2>${!cards.length?`<div class="card empty">🎉 太棒了！目前沒有需要再練的單字！</div>`:`<div class="grid cards">${cards.map(c=>`<button class="flash" onclick="speak('${c.word}')">${cardImage(c)}<span class="speaker">🔊</span></button>`).join("")}</div>${btn("開始再練一次","pink","startPractice()")}`}`}
function startPractice(){const ids=Object.keys(active().mistakes||{}),targets=state.cards.filter(c=>ids.includes(c.id));if(!targets.length){go("mistakes");return}const learned=state.cards.filter(c=>(active().learned||[]).includes(c.topicId)),pool=learned.length>=4?learned:state.cards;state.questions=assignTypes(shuffled(targets)).map(q=>({...q,opts:options(q.card,pool)}));state.qIndex=0;state.score=0;state.practice=true;go("quiz")}
function renderPracticeResult(){const left=Object.keys(active().mistakes||{}).length;document.getElementById("page").innerHTML=`<h2 class="pageTitle">複習完成</h2><div class="card result"><div style="font-size:64px">📚</div><h2>${left?`還有 ${left} 個單字待複習`:"太棒了！錯題已清空！"}</h2><div class="settingsRow" style="justify-content:center">${left?btn("再練一次","pink","startPractice()"):""}${btn("回主選單","primary","go('menu')")}</div></div>`}
function renderProfile(){const p=active();const learnedCards=state.cards.filter(c=>(p.learned||[]).includes(c.topicId)).length;const uniqueLearned=[...new Set(p.learned||[])].length;const themes=rewardThemesFor(p);const totalOwned=themes.reduce((n,t)=>n+((p.rewardImages?.[t.id]||[]).length),0);const totalAll=themes.reduce((n,t)=>n+t.imgs.length,0);const completed=themes.filter(t=>(p.rewardImages?.[t.id]||[]).length===t.imgs.length).length;document.getElementById("page").innerHTML=`<h2 class="pageTitle">我的寶物</h2><div class="card result treasurePage">${avatarImg(p.avatar,"big")}<h1 style="color:var(--indigo)">${esc(p.name)}</h1><div class="statsRow"><span>📖 已學 ${uniqueLearned} 個單元 · ${learnedCards} 個單字</span><span>📝 測驗 ${p.quizzes||0} 次</span></div><section class="treasureHero"><div class="treasureSummary"><div class="treasureNum">${totalOwned}<small> / ${totalAll}</small></div><div><b>寶物收藏進度</b><br><small>完成 ${completed} 個主題收藏</small></div></div><div class="treasureSummary"><div class="treasureNum">${completed}</div><div><b>收藏徽章</b><br><small>集滿整套就能得到 🏅</small></div></div></section><section class="puzzles"><h3>寶箱獎勵收藏</h3><p class="rewardHint">${rewardGroupFor(p)==="girl"?"女生角色獎勵收藏":"男生角色獎勵收藏"}</p>${rewardCollectionHtml(p)}</section><hr><button class="btn danger" onclick="confirmDelete()">🗑 刪除此玩家存檔</button><div id="deleteConfirm"></div></div>`}
function confirmDelete(){document.getElementById("deleteConfirm").innerHTML=`<div class="status"><p><b>確定刪除所有紀錄嗎？</b></p>${btn("確定刪除","danger","deleteProfile()")} ${btn("取消","","renderProfile()")}</div>`}
function deleteProfile(){state.profiles=state.profiles.filter(p=>p.id!==state.activeId);state.activeId=null;saveProfiles();go("profiles")}
boot();
